INSERT INTO `issues` (`id`, `issue`, `analisa`, `risk`, `solution`, `keterangan`, `status`, `profile_affected`) VALUES
(1, 'Perangkat DDF yang sudah Power Off', 'Perangkat sudah tidak digunakan', 'Mengganggu operasional menjadi tidak maksimal', 'Dismantle perangkan DDF', 'Sudah dilaporkan (Update 05/08/2025)', 'Open', 'Power'),
(2, 'Area gedung TTC terdapat retakan termasuk di dalam area ruang-ruang perangkat', 'Disebabkan oleh bencana gempa bumi di bulan september 2023', 'Kondisi ini sangat serius, karena jika dibiarkan kemudian terjadi bencana gempa bumi resikonya menjadi lebih besar', 'Melakukan Revitalasi gedung TTC secara menyeluruh', 'Masuk dalam Project revitalisasi gedung by PT. Karsa Prabala', 'On Progress', 'Building'),
(3, 'Tidak ada Hydrant', 'Belum ada Hydrant', 'Apabila terjadi kebakaran penanganannya tidak maksimal', 'Pengadaan Hydrant', 'Masuk dalam Project by PT. CIS', 'On Progress', 'FSS'),
(4, 'Kerusakan pada Motherboard & Display PAC 013 RCG R. Battery', 'Ditemukan kerusakan port LAN pada Motherboard', 'Menyebabkan mengoperasikan cooling system tidak maksimal', 'Mengganti baru Motherboard & Display', 'Sudah masuk dalam project by PT. Westindo', 'Close', 'Cooling System'),
(5, 'Keramik pada koridor Lt. 2 beberapa ada yang sudah rusak', 'Kondisi usia lantai sudah lama dan aktivitas sehari-hari', 'Kerusakan lantai semakin parah dan mengganggu aktivitas di jalur koridor', 'Penggantian keramik lantai koridor lantai 2', 'Masuk dalam Project Revitalisasi gedung by PT Karsa', 'On Progress', 'Building'),
(6, 'Lantai rooftop beberapa ada yang sudah rusak', 'Kondisi usia lantai sudah lama dan aktivitas sehari-hari', 'Menyebabkan kebocoran dan air dapat masuk ke dalam ruang perangkat', 'Penggantian lapisan lantai rooftop', 'Masuk dalam Project Revitalisasi gedung by PT Karsa', 'On Progress', 'Building'),
(7, 'Beberapa sisi rooftop tidak terdapat pagar', 'Belum ada pagar di beberapa sisi rooftop', 'Bisa menyebabkan kecelakaan pada pekerja', 'Penambahan pagar rooftop', 'Masuk dalam Project Revitalisasi gedung by PT Karsa', 'On Progress', 'Building'),
(8, 'Terdapat kaca di beberapa ruangan perangkat pada TTC', 'Ada kaca di beberapa bagian ruang perangkat', 'Karena berdasarkan aturan bahwa pada TTC tidak boleh ada kaca pada bagian ruang perangkat', 'Menutup sisi gedung dengan beton yang masih terdapat kaca', 'Masuk dalam Project Revitalisasi gedung by PT Karsa', 'On Progress', 'Building'),
(9, 'Pintu emergency lantai 2 masih tipe pintu 1 arah', 'Perlu diganti pintu 2 arah', 'Apabila terjadi bencana untuk mengevakuasi menjadi tidak maksimal', 'Mengganti pintu emergency lantai 2 dengan tipe swing (2 arah)', 'Masuk dalam Project Revitalisasi gedung by PT Karsa', 'On Progress', 'Building'),
(10, 'Karpet roll R. Core yang sering terlepas', 'Karena usia karpet sudah lama', 'Bisa menyebabkan kecelakaan pada pekerja', 'Mengganti karpet roll dengan yang baru', 'Masuk dalam Project Revitalisasi gedung by PT Karsa', 'On Progress', 'Building'),
(11, 'Tidak ada COS', 'Belum ada COS', 'Apabila terjadi pemadaman menyebabkan gangguan pada operasional', 'Pengadaan COS dan panel power', 'Sudah dilaporkan (Update 05/08/2025)', 'Open', 'Power'),
(12, 'Terdapat kerusakan sensor oli pada Genset 2', 'Karena usia sensor oli sudah lama', 'Mengganggu operasional menjadi tidak maksimal', 'Mengganti sensor oli dengan yang baru', 'Sudah dilaporkan (Update 05/08/2025)', 'Open', 'Power'),
(13, 'Tidak ada kanopi pada tangki bulanan BBM', 'Belum ada kanopi', 'Operasional menjadi tidak maksimal', 'Pengadaan kanopi untuk tangki bulanan', 'Sudah dilaporkan (Update 05/08/2025)', 'Open', 'Building'),
(14, 'Terdapat 5 Modul pada Rectifier mengalami Faulty', 'Module faulty dikarenakan debu', 'Operasional Power system kurang maksimal', 'Mengganti Module rectifier', 'Sudah diganti dengan module baru', 'Close', 'Power'),
(15, 'Terdapat 3 Module mengalami faulty pada UPS 1.01 Liebert', 'Module faulty dikarenakan debu', 'Operasional Power system kurang maksimal', 'Mengganti Module UPS', 'Module yang rusak sudah diganti, saat ini UPS 1.01 beroperasi dengan 3 Module service', 'Close', 'Power'),
(16, 'Terdapat 1 Module mengalami faulty pada UPS 1.02 Eaton', 'Module faulty dikarenakan debu', 'Operasional Power system kurang maksimal', 'Mengganti Module UPS', 'Module yang rusak sudah diganti, namun UPS 1.02 masih alarm pada display', 'Close', 'Power'),
(17, 'Terdapat 3 Module pada Rectifier 1.4 mengalami Faulty', 'Module faulty dikarenakan debu', 'Operasional Power system kurang maksimal', 'Mengganti Module rectifier', 'Sudah diganti dengan module baru', 'Close', 'Power'),
(18, 'Terdapat 2 Module pada Rectifier 1.2 mengalami Faulty', 'Module faulty dikarenakan debu', 'Operasional Power system kurang maksimal', 'Mengganti Module rectifier', 'Sudah diganti dengan module baru', 'Close', 'Power'),
(19, 'Terdapat 3 Module mengalami faulty pada UPS 1.02 Eaton', 'Module faulty dikarenakan debu', 'Operasional Power system kurang maksimal', 'Mengganti Module UPS', 'Sudah diganti dengan module baru', 'Close', 'Power'),
(20, 'Terdapat kerusakan pada Fuse CBMS Bank 1 & 2 UPS 1.02 Eaton', 'Terjadi kerusakan karena terdampak dari UPS 1.02 Shutdown', 'Kondisi ini sangat serius, karena CBMS tidak terconnect dengan UPS 1.02 sehingga ketika PLN OFF UPS 1.02 tidak akan terbackup', 'Mengganti Fuse CBMS', 'Sudah diganti dengan Fuse baru', 'Close', 'Power'),
(21, 'Terdapat 1 Module pada Rectifier 1.2 mengalami faulty', 'Module faulty dikarenakan debu', 'Operasional Power system kurang maksimal', 'Mengganti Module rectifier', 'Sudah diganti dengan module baru', 'Close', 'Power');
